import contextlib,datetime,io,json,pathlib,subprocess
buf=io.StringIO()
with contextlib.redirect_stdout(buf):exec(compile(b'import datetime,json,os,pathlib,stat\nexec("def collect_hardware():\\n rows={}\\n for raw in [\'/opt/lims\',\'/var/lib/docker\',\'/var/lib/containerd\']:\\n  p=pathlib.Path(raw)\\n  for a in [p,*p.parents]:\\n   if a.is_symlink():raise RuntimeError(\'Hardware ancestor alias\')\\n  if str(p.resolve(strict=True))!=raw or not p.is_dir():raise RuntimeError(\'Hardware path is not its canonical directory\')\\n  s=p.stat();v=os.statvfs(p)\\n  if type(s.st_dev) is not int or s.st_dev<0 or type(v.f_bavail) is not int or v.f_bavail<0 or v.f_bsize!=4096 or v.f_frsize!=4096:raise RuntimeError(\'Exact4096 statvfs hardware required\')\\n  rows[raw]={\'path\':raw,\'realpath\':str(p.resolve(strict=True)),\'ancestorsChecked\':True,\'directory\':True,\'device\':s.st_dev,\'blockBytes\':v.f_bsize,\'fragmentBytes\':v.f_frsize,\'availableBlocks\':v.f_bavail,\'freeBytes\':v.f_bavail*v.f_frsize}\\n return rows\\n")\ndata=pathlib.Path(\'/opt/lims/releases/workflow-batch-stopped-copy-cde8c889-20261015T080000Z/installed-209/raw\')/\'dev.db\';assets=pathlib.Path(\'/opt/lims/releases/workflow-batch-stopped-copy-cde8c889-20261015T070000Z/raw-production-assets\')\ndef meta(p):\n for a in [p,*p.parents]:assert not a.is_symlink()\n if not p.exists():return None\n s=p.stat();assert stat.S_ISREG(s.st_mode)\n return (s.st_size,s.st_blocks*512,s.st_ino,s.st_mtime_ns,s.st_dev)\ntriple=lambda:[meta(pathlib.Path(str(data)+n)) for n in [\'\',\'-wal\',\'-shm\']]\nbefore=triple();backupPath=pathlib.Path(\'/opt/lims/releases/workflow-batch-stopped-copy-cde8c889-20261015T080000Z/installed-209/backup.db\');backupBefore=meta(backupPath);assert before[0] is not None and backupBefore is not None;rows=[];directoryCount=0\nfor a in [assets,*assets.parents]:assert not a.is_symlink()\nassert assets.is_dir()\nfor directory,children,files in os.walk(assets,followlinks=False):\n p=pathlib.Path(directory);assert not p.is_symlink() and p.stat().st_dev==assets.stat().st_dev\n directoryCount+=1;assert directoryCount<=7,\'Pinned asset directory maximum exceeded\'\n for n in children:assert not (p/n).is_symlink()\n for n in files:\n  row=meta(p/n);assert row and row[4]==assets.stat().st_dev;rows.append(row);assert len(rows)<=200000\nassert triple()==before and meta(backupPath)==backupBefore,\'Metadata changed: STOP, no retry\'\nallocation=lambda r:max(r[1],((r[0]+4095)//4096)*4096)\nt=max(sum(allocation(r) for r in before if r),allocation(backupBefore));a=sum(allocation(r) for r in rows)\nhardware=collect_hardware()\nprint(json.dumps({\'metadataOnly\':True,\'observedUtc\':datetime.datetime.now(datetime.timezone.utc).isoformat(),\'phase\':\'BEFORE_UNIT\',\'futurePackageBytes\':0,\'databaseReserveBytes\':t,\'assetReserveBytes\':a,\'assetDirectoryCount\':directoryCount,\'requiredBytes\':24851691630+30*t+3*a+0,\'additionalHeadroomBytes\':10000000000,\'dbEquivalents\':30,\'stageTableSha256\':\'627c4aa5ee89c0991a4af527bf98c3cd8b3a84855f049930d04b3c223bed54e9\',\'hardware\':hardware,\'freeBytes\':{p:r[\'freeBytes\'] for p,r in hardware.items()},\'productionContentOpens\':0,\'productionCopies\':0,\'sqlConnections\':0}))\n','actual-capacity-reference','exec'),{})
capacity=json.loads(buf.getvalue())
root=pathlib.Path('/opt/lims/releases/workflow-batch-startup-memory-be837974-20261015T233000Z');unit='lims-workflow-batch-startup-memory-be837974-20261015t233000z'
assert not root.exists() and not root.is_symlink()
